"""生成测试语料：用 Edge-TTS 合成一段已知文本的语音，供训练流水线冒烟测试。"""
import asyncio, edge_tts

SENTENCES = [
    "清晨的阳光透过窗帘洒进房间，新的一天开始了。",
    "他端起桌上的茶杯，轻轻吹了吹热气，慢慢喝了一口。",
    "窗外的树叶在微风中轻轻摇晃，发出沙沙的声响。",
    "远处的山峦笼罩在薄雾之中，显得格外宁静。",
    "孩子们在院子里追逐玩耍，笑声传得很远很远。",
    "母亲在厨房里准备早餐，锅碗瓢盆发出清脆的碰撞声。",
    "街道上的行人渐渐多了起来，城市慢慢苏醒过来。",
    "他打开电脑，开始处理今天的工作邮件和待办事项。",
    "午后的阳光有些刺眼，他拉上了半边的窗帘。",
    "书架上摆满了各种各样的书籍，从历史到科学应有尽有。",
    "天气预报告诉我们，明天可能会有阵雨，记得带伞。",
    "他喜欢在傍晚的时候沿着河边散步，看夕阳慢慢落下。",
    "夜晚的城市灯火通明，车流像一条流动的河流。",
    "她坐在书桌前，写下今天的日记和明天要做的事情。",
    "时间过得真快，转眼间一年又过去了大半。",
    "无论遇到什么困难，都要保持乐观的心态去面对生活。",
]

async def main():
    # 每句单独合成再拼接，避免单次请求过长
    for i, s in enumerate(SENTENCES):
        c = edge_tts.Communicate(s, "zh-CN-XiaoxiaoNeural")
        await c.save(f"part_{i:02d}.mp3")
        print(f"  [{i+1}/{len(SENTENCES)}] {s[:20]}...")

asyncio.run(main())
